// ===== EDIT THIS BLOCK PER CLIENT =====
const BUSINESS = {
  name: 'Sample Barbershop',
  hours: 'Mon-Sat 9:00 AM to 8:00 PM, closed Sunday',
  location: '123 Sample St., Quezon City',
  prices: 'Haircut P250, Haircut + Shave P350, Hair color from P800',
  booking: 'Customers can book at https://example.com/book',
  other: 'Walk-ins welcome. Cancel at least 3 hours before the appointment.'
};
// =======================================

const body = $input.first().json.body;
const m = body && body.entry && body.entry[0] && body.entry[0].messaging && body.entry[0].messaging[0];
if (!m || !m.message || m.message.is_echo || !m.message.text) return [];

const system = `You are the friendly Messenger assistant of ${BUSINESS.name}.
Reply in the same language as the customer (English, Tagalog or Taglish). Keep replies short (max 3 sentences).
Use ONLY these facts:
- Hours: ${BUSINESS.hours}
- Location: ${BUSINESS.location}
- Prices: ${BUSINESS.prices}
- Booking: ${BUSINESS.booking}
- Other: ${BUSINESS.other}
Never invent prices, times or policies. Never promise a booking slot.
If the customer wants to book, share the booking link.
If you do not know the answer, or the customer is upset, wants a refund, or asks for a person, reply with exactly: [HANDOFF]`;

return [{ json: { senderId: m.sender.id, text: m.message.text, system } }];

const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';
const handoff = raw.includes('[HANDOFF]') || raw.trim() === '';
const replyText = handoff ? 'Salamat po! A staff member will reply to you shortly.' : raw.trim();
const src = $('Extract Message').first().json;
return [{ json: { senderId: src.senderId, customerText: src.text, handoff, replyText } }];

